def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    if old == 0:
        return None

    change = new - old
    change_ratio = (change / old) * 100

    return {
        "value": change_ratio,
        "trace": {
            "old_liability": old,
            "new_liability": new,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": "percentage"
            }
        }
    }
